import re
import json

with open('doc/superhero.md', 'r') as f:
    content = f.read()

# Split into blocks
blocks = content.split('\n\n')

# First pass: collect registration IDs and their associated blocks
block_by_reg = {}  # reg_id -> list of block indices

for block_idx, block in enumerate(blocks):
    reg_matches = re.findall(r'(?:registration|identifier|registry|ID)[\s:]*(?:number|\s+)?([\d]+)', block, re.IGNORECASE)
    for reg_id in reg_matches:
        if reg_id not in block_by_reg:
            block_by_reg[reg_id] = []
        block_by_reg[reg_id].append(block_idx)

# Second pass: for each registration ID, extract name, height, publisher from its block
hero_data = {}

for reg_id, block_indices in block_by_reg.items():
    hero_data[reg_id] = {'name': None, 'height': None, 'publisher': None}

    for block_idx in block_indices:
        block = blocks[block_idx]

        # Extract name - look for hero names
        name_patterns = [
            r'(?:hero|operative|unit|file for [a-z]+\s+|cataloged as|known as|designated)\s+([A-Z][a-z]+(?:\s+the\s+|\s+II|\s+III|\s+IV|\s+V|\s+VI|\s+VII|\s+VIII|\s+IX|\s+X|\s+XI|\s+XII|\s+XIII|\s+XIV|\s+XV|\s+XVI|\s+XVII|\s+XVIII|\s+XIX|\s+XX)?\s+[A-Z][a-z]*)',
            r'(?:For |the )([A-Z][a-z]+(?:\s+II|\s+III|\s+IV|\s+V|\s+VI|\s+VII|\s+VIII|\s+IX|\s+X)?\s+(?:and |\s+[A-Z][a-z]+)?)',
            r'([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*(?:\s+(?:the|II|III|IV|V|VI|VII|VIII|IX|X|XI|XII|XIII|XIV|XV|XVI|XVII|XVIII|XIX|XX))?\s*[,.]?|^[A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)',
        ]

        for pattern in name_patterns:
            name_match = re.search(pattern, block, re.IGNORECASE)
            if name_match:
                name = name_match.group(1).strip() if name_match.lastindex else name_match.group(0).strip()
                name = re.sub(r'^The\s+', '', name, flags=re.IGNORECASE)
                name = re.sub(r'\s+[,.]+$', '', name)
                if len(name) > 2 and not hero_data[reg_id]['name']:
                    hero_data[reg_id]['name'] = name
                    break

        # Extract height
        height_match = re.search(r'height.*?([\d.]+)\s*(?:centimeters|cm)', block, re.IGNORECASE)
        if height_match:
            height = float(height_match.group(1))
            if not hero_data[reg_id]['height']:
                hero_data[reg_id]['height'] = height

        # Extract publisher
        pub_match = re.search(r'[Pp]ublisher\s+affiliation\s+as\s+(\d+)', block)
        if pub_match:
            if not hero_data[reg_id]['publisher']:
                hero_data[reg_id]['publisher'] = int(pub_match.group(1))

print(f"Total heroes collected: {len(hero_data)}")
print(f"Heroes with height: {sum(1 for h in hero_data.values() if h['height'])}")
print(f"Heroes with publisher: {sum(1 for h in hero_data.values() if h['publisher'])}")

# Find heroes in height range 150-180 cm
height_range_heroes = {k: v for k, v in hero_data.items() if v['height'] and 150 <= v['height'] <= 180}
print(f"\nHeroes in height range 150-180: {len(height_range_heroes)}")

marvel_heroes = {k: v for k, v in height_range_heroes.items() if v['publisher'] == 13}
print(f"Marvel heroes (ID 13) in range: {len(marvel_heroes)}")

print("\nHeroes in range 150-180 cm:")
for reg_id, data in sorted(height_range_heroes.items(), key=lambda x: x[1]['height'] or 0):
